// P569 — capacity, bed transfer, waitlist and controlled checkout/settlement.
hostelRouter.get(base+"/capacity",wrap(async(req,res)=>{
 const s=await scope(req,res);if(!s)return;
 const rows=await withTenantContext(prisma,s,tx=>tx.hostelBed.findMany({where:{organizationId:s.organizationId,schoolId:s.schoolId},include:{room:{include:{building:true}}}}));
 const counts:any={total:rows.length,occupied:0,reserved:0,available:0,maintenance:0,outOfService:0,other:0,byBuilding:{}};
 for(const bed of rows){const status=String(bed.status||'').toUpperCase();const key=status==='OCCUPIED'?'occupied':status==='RESERVED'?'reserved':status==='AVAILABLE'?'available':status==='MAINTENANCE'?'maintenance':(['OUT_OF_SERVICE','OUT-OF-SERVICE'].includes(status)?'outOfService':'other');counts[key]++;const building=bed.room?.building?.name||'Unassigned';counts.byBuilding[building]??={total:0,occupied:0,reserved:0,available:0,maintenance:0,outOfService:0};counts.byBuilding[building].total++;counts.byBuilding[building][key]=(counts.byBuilding[building][key]||0)+1;}
 res.json({data:counts});
}));
hostelRouter.post(base+"/transfers",wrap(async(req,res)=>{
 const s=await scope(req,res,"hostel.manage");if(!s)return;
 const p=z.object({allocationId:z.string().min(1),toBedId:z.string().min(1),effectiveAt:z.string().datetime().optional(),reason:z.string().trim().min(3).max(1000)}).safeParse(req.body);
 if(!p.success)return res.status(400).json({error:"Invalid bed transfer",details:p.error.flatten()});
 const result=await withTenantContext(prisma,s,async tx=>{
  const allocation=await tx.hostelAllocation.findFirst({where:{id:p.data.allocationId,organizationId:s.organizationId,schoolId:s.schoolId,status:"ACTIVE"}});
  if(!allocation)throw Object.assign(new Error("Active resident allocation not found"),{status:404});
  await tx.$queryRawUnsafe("SELECT pg_advisory_xact_lock(hashtextextended($1, 0))",`${s.organizationId}:${s.schoolId}:hostel-transfer:${allocation.studentId}`);
  const current=await tx.hostelBed.findFirst({where:{id:allocation.bedId,organizationId:s.organizationId,schoolId:s.schoolId,status:"OCCUPIED"},include:{room:{include:{building:true}}}});
  const target=await tx.hostelBed.findFirst({where:{id:p.data.toBedId,organizationId:s.organizationId,schoolId:s.schoolId},include:{room:{include:{building:true}}}});
  if(!current||!target)throw Object.assign(new Error("Source or destination bed not found"),{status:404});
  if(target.status!=="AVAILABLE")throw Object.assign(new Error("Destination bed is not available"),{status:409});
  const student=await tx.student.findFirst({where:{id:allocation.studentId,organizationId:s.organizationId,schoolId:s.schoolId},select:{id:true,gender:true}});
  if(!student)throw Object.assign(new Error("Student not found in this school"),{status:404});
  const targetType=target.room.building.hostelType;
  if(targetType==='BOYS'&&student.gender==='FEMALE'||targetType==='GIRLS'&&student.gender==='MALE')throw Object.assign(new Error("Destination hostel type is not eligible for this student"),{status:409});
  const claimed=await tx.hostelBed.updateMany({where:{id:target.id,organizationId:s.organizationId,schoolId:s.schoolId,status:"AVAILABLE"},data:{status:"OCCUPIED"}});
  if(claimed.count!==1)throw Object.assign(new Error("Destination bed was allocated concurrently"),{status:409});
  await tx.hostelAllocation.update({where:{id:allocation.id},data:{bedId:target.id}});
  await tx.hostelBed.update({where:{id:current.id},data:{status:"AVAILABLE"}});
  await offerNextWaitlistEntry(tx,s,current.id);
  const transfer=await tx.hostelBedTransfer.create({data:{organizationId:s.organizationId,schoolId:s.schoolId,allocationId:allocation.id,studentId:allocation.studentId,fromBedId:current.id,toBedId:target.id,effectiveAt:p.data.effectiveAt?new Date(p.data.effectiveAt):new Date(),reason:p.data.reason,requestedBy:s.userId,approvedBy:s.userId}});
  await audit(s,tx,"HOSTEL_BED_TRANSFERRED","HostelBedTransfer",transfer.id,{allocationId:allocation.id,fromBedId:current.id,toBedId:target.id,reason:p.data.reason});return transfer;
 });res.status(201).json({data:result});
}));
