hostelRouter.post(base+"/waitlist/:entryId/decline",wrap(async(req,res)=>{const s=await scope(req,res,"hostel.manage");if(!s)return;const data=await withTenantContext(prisma,s,async tx=>{const entry=await tx.hostelWaitlistEntry.findFirst({where:{id:req.params.entryId,organizationId:s.organizationId,schoolId:s.schoolId,status:"OFFERED"}});if(!entry)return null;await tx.hostelWaitlistEntry.update({where:{id:entry.id},data:{status:"DECLINED",declinedAt:new Date()}});if(entry.offeredBedId){await tx.hostelBed.updateMany({where:{id:entry.offeredBedId,organizationId:s.organizationId,schoolId:s.schoolId,status:"RESERVED"},data:{status:"AVAILABLE"}});await offerNextWaitlistEntry(tx,s,entry.offeredBedId);}return {updated:true};});if(!data)return res.status(404).json({error:"Open waitlist offer not found"});res.json({data});}));
