 if(!p.success)return res.status(400).json({error:"Invalid checkout clearance",details:p.error.flatten()});
 const d=p.data;const result=await withTenantContext(prisma,s,async tx=>{const a=await tx.hostelAllocation.findFirst({where:{id:req.params.allocationId,organizationId:s.organizationId,schoolId:s.schoolId,status:"ACTIVE"}});if(!a)throw Object.assign(new Error("Active allocation not found"),{status:404});await tx.$queryRawUnsafe("SELECT pg_advisory_xact_lock(hashtextextended($1, 0))",`${s.organizationId}:${s.schoolId}:hostel-checkout:${a.id}`);const {settlementLines,...clearance}=d;const checkout=await tx.hostelCheckout.upsert({where:{organizationId_schoolId_allocationId:{organizationId:s.organizationId,schoolId:s.schoolId,allocationId:a.id}},create:{organizationId:s.organizationId,schoolId:s.schoolId,allocationId:a.id,studentId:a.studentId,requestedBy:s.userId,...clearance},update:clearance});await tx.hostelSettlementLine.deleteMany({where:{checkoutId:checkout.id,organizationId:s.organizationId,schoolId:s.schoolId}});if(settlementLines.length)await tx.hostelSettlementLine.createMany({data:settlementLines.map(x=>({...x,checkoutId:checkout.id,organizationId:s.organizationId,schoolId:s.schoolId}))});await audit(s,tx,"HOSTEL_CHECKOUT_CLEARANCE_UPDATED","HostelCheckout",checkout.id,{allocationId:a.id,settlementLineCount:settlementLines.length});return tx.hostelCheckout.findUnique({where:{id:checkout.id},include:{settlementLines:true}});});res.json({data:result});
