hostelRouter.post(p570+"/deposits/:accountId/refund-requests",wrap(async(req,res)=>{const s=await scope(req,res,"hostel.manage");if(!s)return;const p=z.object({amount:z.number().positive().max(10000000),reason:z.string().trim().min(3).max(1000)}).safeParse(req.body);if(!p.success)return res.status(400).json({error:"Invalid refund request"});const data=await withTenantContext(prisma,s,async tx=>{const a=await tx.hostelDepositAccount.findFirst({where:{id:req.params.accountId,organizationId:s.organizationId,schoolId:s.schoolId,status:"OPEN"}});if(!a)throw Object.assign(new Error("Open deposit account not found"),{status:404});const pending=await tx.hostelDepositEvent.aggregate({where:{organizationId:s.organizationId,schoolId:s.schoolId,accountId:a.id,eventType:"REFUND_REQUEST",status:{in:["PENDING","APPROVED"]}},_sum:{amount:true}});const available=Number(a.balance)-Number(pending._sum.amount||0);if(p.data.amount>available)throw Object.assign(new Error("Refund request exceeds uncommitted deposit balance"),{status:409});const event=await tx.hostelDepositEvent.create({data:{organizationId:s.organizationId,schoolId:s.schoolId,accountId:a.id,eventType:"REFUND_REQUEST",status:"PENDING",amount:p.data.amount,reason:p.data.reason,requestedBy:s.userId}});await audit(s,tx,"HOSTEL_DEPOSIT_REFUND_REQUESTED","HostelDepositEvent",event.id,{accountId:a.id,amount:p.data.amount});return event});res.status(201).json({data});}));
hostelRouter.post(p570+"/deposits/:accountId/refund-requests/:eventId/approve",wrap(async(req,res)=>{const s=await scope(req,res,"hostel.manage");if(!s)return;const data=await withTenantContext(prisma,s,async tx=>{const e=await tx.hostelDepositEvent.findFirst({where:{id:req.params.eventId,accountId:req.params.accountId,organizationId:s.organizationId,schoolId:s.schoolId,eventType:"REFUND_REQUEST",status:"PENDING"}});if(!e)throw Object.assign(new Error("Pending refund request not found"),{status:404});const approved=await tx.hostelDepositEvent.update({where:{id:e.id},data:{status:"APPROVED",approvedBy:s.userId,approvedAt:new Date()}});await audit(s,tx,"HOSTEL_DEPOSIT_REFUND_APPROVED","HostelDepositEvent",e.id,{amount:Number(e.amount)});return approved});res.json({data});}));
hostelRouter.post(p570+"/deposits/:accountId/refund-requests/:eventId/execute",wrap(async(req,res)=>{const s=await scope(req,res,"hostel.manage");if(!s)return;const data=await withTenantContext(prisma,s,async tx=>{await tx.$queryRawUnsafe("SELECT pg_advisory_xact_lock(hashtextextended($1, 0))",`${s.organizationId}:${s.schoolId}:hostel-deposit:${req.params.accountId}`);const e=await tx.hostelDepositEvent.findFirst({where:{id:req.params.eventId,accountId:req.params.accountId,organizationId:s.organizationId,schoolId:s.schoolId,eventType:"REFUND_REQUEST",status:"APPROVED"}});if(!e)throw Object.assign(new Error("Approved, unexecuted refund request not found"),{status:404});const a=await tx.hostelDepositAccount.findFirst({where:{id:e.accountId,organizationId:s.organizationId,schoolId:s.schoolId,status:"OPEN"}});if(!a||Number(a.balance)<Number(e.amount))throw Object.assign(new Error("Refund balance is no longer available"),{status:409});const executed=await tx.hostelDepositEvent.update({where:{id:e.id},data:{status:"EXECUTED",executedBy:s.userId,executedAt:new Date()}});const account=await tx.hostelDepositAccount.update({where:{id:a.id},data:{refundedAmount:{increment:Number(e.amount)},balance:{decrement:Number(e.amount)}}});await audit(s,tx,"HOSTEL_DEPOSIT_REFUND_EXECUTED","HostelDepositEvent",e.id,{amount:Number(e.amount)});return{account,event:executed}});res.json({data});}));
